"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(Head):
    Slow = Head
    Fast = Head
    while ((Fast is not None) and (Fast.Next is not None)):
        Slow = Slow.Next
        Fast = Fast.Next.Next
        if (Slow == Fast):
            print('Cycle Detected')
            return
    print('No Cycle')
class Node:
    def __init__(self, value):
        self.Value = value
        self.Next = None



# Create nodes
A = Node(1)
B = Node(2)
C = Node(3)
D = Node(4)

# Link them
A.Next = B
B.Next = C
C.Next = D

# Create cycle: D → B
D.Next = B

# Test
unnamed_function(A)


